def fig(body,w=320,h=210):return svg('<g font-family="serif" font-size="19">'+body+'</g>',w,h)
def add(n,p,r,text,level='medium',kind='fill',**kw):
    paper.add(n,p,[v*1.7/1.5 for v in r],text,level,kind,**kw)
def compact_diagrams(pid):
    file=root/f'transcribed-bulk-{pid}.json';rows=json.loads(file.read_text(encoding='utf8'))
    for row in rows:
        if 'diagramSvg' in row:row['blocks'].append({'type':'svg','svg':row.pop('diagramSvg'),'maxHeight':100})
    file.write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
